sys_script_include.script:
var Energir_IRMUtils = Class.create();
Energir_IRMUtils.prototype = {
    initialize: function() {},
    createRecordFromSource: function(sourceRecord, targetTable, fieldMapping, infomsg) {
        if (!sourceRecord || !targetTable || !fieldMapping) {
            gs.addErrorMessage("Invalid parameters provided.");
            return;
        }

        var targetRecord = new GlideRecord(targetTable);
        targetRecord.initialize();

        for (var sourceField in fieldMapping) {
            if (sourceRecord.isValidField(sourceField)) {
                targetRecord.setValue(fieldMapping[sourceField], sourceRecord.getValue(sourceField));
            }
        }

        var newSysId = targetRecord.insert();
        if (!newSysId) {
            gs.addErrorMessage("Failed to create record in " + targetTable);
            return;
        }

        var recordUrl = gs.getProperty('glide.servlet.uri') + targetTable + ".do?sys_id=" + newSysId;
        var clickableLink = '<a href="' + recordUrl + '">' + targetRecord.getDisplayValue('number') + '</a>';

        gs.addInfoMessage(gs.getMessage(infomsg) + clickableLink);
    },
    type: 'Energir_IRMUtils'
};
